const ArgumentType = require("../../extension-support/argument-type");
const BlockType = require("../../extension-support/block-type");
const Cast = require("../../util/cast");
const log = require("../../util/log");

/**
 * Icon svg to be displayed at the left edge of each extension block, encoded as a data URI.
 * @type {string}
 */
// eslint-disable-next-line max-len
const blockIconURI =
    "data:image/svg+xml;base64,";

/**
 * Icon svg to be displayed in the category menu, encoded as a data URI.
 * @type {string}
 */
// eslint-disable-next-line max-len
const menuIconURI =
    "data:image/svg+xml;base64,";

/**
 * Class for the new blocks in Scratch 3.0
 * @param {Runtime} runtime - the runtime instantiating this block package.
 * @constructor
 */
class Scratch3Webkit {
    constructor(runtime) {
        /**
         * The runtime instantiating this block package.
         * @type {Runtime}
         */
        this.runtime = runtime;

        //this._onTargetCreated = this._onTargetCreated.bind(this);
        //this.runtime.on('targetWasCreated', this._onTargetCreated);
    }
    /**
     * @returns {object} metadata for this extension and its blocks.
     */
    getInfo() {
        return {
            id: "webkit",
            name: "Web kit",
            menuIconURI: menuIconURI,
            blockIconURI: blockIconURI,
            blocks: [
                {
                    opcode: "writeLog",
                    blockType: BlockType.COMMAND,
                    text: "alert [TEXT]",
                    arguments: {
                        TEXT: {
                            type: ArgumentType.STRING,
                            defaultValue: "Scratch",
                        },
                    },
                },
                {
                    opcode: "writeConfirm",
                    text: "confirm [TEXT]",
                    arguments: {
                        TEXT: {
                            type: ArgumentType.STRING,
                            defaultValue: "Do you like scratch?",
                        },
                    },
                    blockType: BlockType.BOOLEAN,
                },
                {
                    opcode: "writePrompt",
                    text: "prompt [TEXT] with defalt value of [ANS]",
                    arguments: {
                        TEXT: {
                            type: ArgumentType.STRING,
                            defaultValue: "What's your name?",
                        },
                        ANS: {
                            type: ArgumentType.STRING,
                            defaultValue: "",
                        },
                    },
                    blockType: BlockType.REPORTER,
                },
                {
                    opcode: "reload",
                    text: "reload",
                    blockType: BlockType.COMMAND,
                },
                {
                    opcode: "close",
                    text: "close",
                    blockType: BlockType.COMMAND,
                },
                {
                    opcode: "open",
                    text: "open [URL]",
                    blockType: BlockType.COMMAND,
                    arguments: {
                        URL: {
                            defaultValue: window.location.href,
                            type: ArgumentType.STRING,
                        },
                    },
                },
                {
                    opcode: "replace",
                    text: "replace the URL with [URL]",
                    blockType: BlockType.COMMAND,
                    arguments: {
                        URL: {
                            defaultValue: window.location.href,
                            type: ArgumentType.STRING,
                        },
                    },
                },
                {
                    opcode: "allways",
                    text: "on start",
                    blockType: BlockType.HAT,
                    isEdgeActivated: true,
                },
                {
                    opcode: "ifReturn",
                    text: "if [BOOLEAN] then return [TRUETEXT], if not then return[FALSETEXT]",
                    blockType: BlockType.REPORTER,
                    arguments: {
                        BOOLEAN: {
                            defaultValue: true,
                            type: ArgumentType.BOOLEAN,
                        },
                        TRUETEXT: {
                            defaultValue: "Scratcher",
                            type: ArgumentType.STRING,
                        },
                        FALSETEXT: {
                            defaultValue: "New Scratcher",
                            type: ArgumentType.STRING,
                        },
                    },
                },
                {
                    opcode: "True",
                    text: "true",
                    blockType: BlockType.BOOLEAN,
                },
                {
                    opcode: "False",
                    text: "false",
                    blockType: BlockType.BOOLEAN,
                },
                {
                    opcode: "Text",
                    text: "[TEXT]",
                    blockType: BlockType.REPORTER,
                    arguments: {
                        TEXT: {
                            defaultValue: "",
                            type: ArgumentType.STRING,
                        },
                    },
                },
                {
                    opcode: "Eval",
                    text: "eval [SCRIPT]",
                    blockType: BlockType.REPORTER,
                    arguments: {
                        SCRIPT: {
                            defaultValue: "alert('scratch!!')",
                            type: ArgumentType.STRING,
                        },
                    },
                },
            ],
            menus: {},
        };
    }

    /**
     * alert.
     * @param {object} args - the block arguments.
     * @property {number} TEXT - the text.
     */
    writeLog(args) {
        const text = Cast.toString(args.TEXT);
        alert(text);
    }

    /**
     * confirm.
     * @param {object} args - the block arguments.
     * @property {number} TEXT - the text.
     * @return {boolean} - the user agent.
     */
    writeConfirm(args) {
        const text = Cast.toString(args.TEXT);
        return confirm(text);
    }
    open(args) {
        const url = Cast.toString(args.URL);
        window.open(url);
    }
    replace(args) {
        const url = Cast.toString(args.URL);
        location.replace(url);
    }
    /**
     * confirm.
     * @param {object} args - the block arguments.
     * @property {number} TEXT - the text.
     * @return {string} - the user agent.
     */
    writePrompt(args) {
        const text = Cast.toString(args.TEXT);
        const ans = Cast.toString(args.ANS);
        if (ans) {
            const a = prompt(text, ans);
            if (a != null) {
                return a;
            } else {
                return false;
            }
        } else {
            return prompt(text);
        }
    }
    reload() {
        location.reload();
    }
    close() {
        window.close();
    }
    allways() {
        return true;
    }
    ifReturn(args) {
        const _boolean = Cast.toBoolean(args.BOOLEAN);
        const trueText = Cast.toString(args.TRUETEXT);
        const falseText = Cast.toString(args.FALSETEXT);
        return _boolean ? trueText : falseText;
    }
    True() {
        return true;
    }
    False() {
        return false;
    }
    Text(args) {
        return Cast.toString(args.TEXT);
    }
    Eval(args) {
        try {
            return eval(Cast.toString(args.SCRIPT));
        } catch (error) {
            return error.toString();
        }
    }
}

module.exports = Scratch3Webkit;