            blocks.push(
                allBlocks.showLessBlocks,
                '---',
                allBlocks.groupBy,
                allBlocks.selectListAllLists,
                allBlocks.orderListAllLists,
                '---',
                allBlocks.mapDataFromTo,
                allBlocks.setData
            );
