	sensorBtnValue({ button }, util) {
		if (!this.waitingForResponse) {
			this.waitingForResponse = true
			output = null
			const command = `sensor.btnValue('${button.toLowerCase()}')`
			this.ws_send(command)
		}
		if (output == null) {
			util.yield();
		} else {
			this.waitingForResponse = false
		}
		return output == "True"
	}

