const ArgumentType = require('../../extension-support/argument-type');
const BlockType = require('../../extension-support/block-type');

let Chronometer_value = 0; //Chronomètre
let Chronometer_enabled = false;
function fChronometer(args) {
  if (args === 'Start') Chronometer_enabled = true;
  if (args === 'Stop') Chronometer_enabled = false;
  if (args === '+Increment') Chronometer_value++;
  if (args === '-Increment') Chronometer_value--;
  if (args === 'Reset') Chronometer_value = 0;
}
setInterval(() => {
    if (Chronometer_enabled === true) Chronometer_value++;
}, 1000);

class Chronometer {
  getInfo() {
    return {
      id: 'adachronometer',
      color1: "#1e9101",
      color2: "#146300",
      name: 'Chronometer',
      blockIconURI: "data:image/svg+xml;base64,",
      blocks: [
        {
          opcode: 'show',
          blockType: BlockType.REPORTER,
          text: 'chronometer'
        }, {
          opcode: 'enable',
          blockType: BlockType.COMMAND,
          text: "start    "
        }, {
          opcode: 'disenable',
          blockType: BlockType.COMMAND,
          text: "pause    "
        }, {
          opcode: 'reset',
          blockType: BlockType.COMMAND,
          text: "stop     "
        }, {
          opcode: 'clear',
          blockType: BlockType.COMMAND,
          text: "clear    "
        }, {
          opcode: 'increment',
          blockType: BlockType.COMMAND,
          text: "add [SECONDS] to chronometer",
          arguments: {
            SECONDS: {
              type: ArgumentType.NUMBER,
              defaultValue: 0
            }
          }
        }, {
          opcode: 'mincrement',
          blockType: BlockType.COMMAND,
          text: 'remove [SECONDS] to chronometer',
          arguments: {
            SECONDS: {
              type: ArgumentType.NUMBER,
              defaultValue: 0
            }
          }
        }
      ]
    }
  }
  show() {
    return Chronometer_value;
  }
  enable() {
    fChronometer('Start');
  }
  disenable() {
    fChronometer('Stop');
  }
  increment(args) {
    Chronometer_value+=Number(args.SECONDS);
  }
  mincrement(args) {
    Chronometer_value-=Number(args.SECONDS);
  }
  reset() {
    fChronometer('Reset');
    fChronometer('Stop');
  }
  clear() {
    fChronometer('Reset');
  }
}
module.exports = Chronometer;
