const ArgumentType = require('../../extension-support/argument-type');
const BlockType = require('../../extension-support/block-type');
const log = require('../../util/log');

// 方块图标链接
const blockIconURI = 'data:image/svg+xml;base64,';


class UDblockMQTT {
    constructor(runtime) {
        this.runtime = runtime;
    }

    getInfo() {
        return {
            id: "udblockMQTT",
            name: "MQTT拓展",
            blockIconURI: blockIconURI,
            blocks: [
                {
                    opcode: "connectMQTT",
                    blockType: BlockType.COMMAND,
                    text: "连接到MQTT服务器[SERVER]",
                    arguments: {
                        SERVER:{
                            type: ArgumentType.STRING,
                            defaultValue: "iot.udrobot.net"
                        }
                    }
                },
                {
                    opcode: "pubTopic",
                    blockType: BlockType.COMMAND,
                    text: "发送话题[TOPIC]内容[MSG]",
                    arguments: {
                        TOPIC:{
                            type: ArgumentType.STRING,
                            defaultValue: "test"
                        },
                        MSG:{
                            type: ArgumentType.STRING,
                            defaultValue: "hello world!"
                        }
                    }
                },
                {
                    opcode: "subTopic",
                    blockType: BlockType.COMMAND,
                    text: "订阅话题[TOPIC]",
                    arguments: {
                        TOPIC:{
                            type: ArgumentType.STRING,
                            defaultValue: "test"
                        },
                        MSG:{
                            type: ArgumentType.STRING,
                            defaultValue: "hello world!"
                        }
                    }
                },
                {
                    opcode: 'mqttClientReceiveEvent',
                    blockType: BlockType.EVHAT,
                    text: '当客户端接收到话题',
                },
                {
                    opcode: 'mqttClientReceivedTopic',
                    blockType: BlockType.REPORTER,
                    text: 'MQTT话题',
                },
                {
                    opcode: 'mqttClientReceivedMsg',
                    blockType: BlockType.REPORTER,
                    text: 'MQTT消息',
                },
            ],
            menus: {
            }
        }
    }
}

module.exports = UDblockMQTT;